import { readFileSync } from "node:fs";
import { join } from "node:path";
import { initializeApp } from "firebase-admin/app";
import { getFirestore } from "firebase-admin/firestore";
import { HttpsError, onCall } from "firebase-functions/v2/https";
import { apply, emptyState, Entry, importLegacy, Rules, sanitize, State } from "./ledger";

export { cancelMatch, confirmWager, matchmake, raceResult, submitRun } from "./race";
export { createCrew, crewHome, editCrew, joinCrew, leaveCrew, manageMember, setName } from "./crews";

initializeApp();
const db = getFirestore();

/** Generated by the game (core LedgerTest) and copied in at build time. */
const rules: Rules = JSON.parse(readFileSync(join(__dirname, "rules.json"), "utf8"));

/** Most entries one call may carry (a Firestore transaction allows 500 writes). */
const MAX_ENTRIES = 400;
/** How far ahead of the server's clock a client timestamp may be. */
const CLOCK_SLACK_MS = 2 * 60_000;
const MAX_PROFILE_CHARS = 400_000;

interface PlayerDoc {
  state: State;
  seq: number;
  profile: string | null;
  imported: boolean;
  created: number;
  updated: number;
}

/**
 * Replays the client's pending ledger entries against the stored state, keeps the ones the rules
 * accept (each also logged under players/{uid}/ledger for audit), and returns the state the
 * client must adopt. Entries are refused, never partly applied.
 *
 * Request: { base, entries: Entry[], profile?: string, legacy?: State-like }
 * Response: { state, seq, rejected: number[], profile: string | null }
 */
export const sync = onCall({ maxInstances: 10, enforceAppCheck: false }, async (req) => {
  if (!req.auth) throw new HttpsError("unauthenticated", "sign in first");
  const uid = req.auth.uid;
  const data = (req.data ?? {}) as Record<string, unknown>;
  const entries = data.entries ?? [];
  if (!Array.isArray(entries) || entries.length > MAX_ENTRIES) throw new HttpsError("invalid-argument", "entries");
  const profile = typeof data.profile === "string" && data.profile.length <= MAX_PROFILE_CHARS ? data.profile : null;

  const ref = db.collection("players").doc(uid);
  return db.runTransaction(async (tx) => {
    const snap = await tx.get(ref);
    const now = Date.now();
    const doc = snap.exists ? (snap.data() as PlayerDoc) : null;
    const state: State = doc ? doc.state : data.legacy ? importLegacy(rules, data.legacy) : emptyState();
    let seq = doc?.seq ?? 0;
    const rejected: number[] = [];
    entries.forEach((raw, i) => {
      const e: Entry | null = sanitize(raw);
      if (!e || e.t > now + CLOCK_SLACK_MS || !apply(rules, state, e)) {
        rejected.push(i);
        return;
      }
      seq++;
      tx.set(ref.collection("ledger").doc(String(seq).padStart(10, "0")), { ...e, at: now });
    });
    const next: PlayerDoc = {
      state,
      seq,
      profile: profile ?? doc?.profile ?? null,
      imported: doc?.imported ?? Boolean(data.legacy),
      created: doc?.created ?? now,
      updated: now,
    };
    tx.set(ref, next);
    return { state, seq, rejected, profile: doc?.profile ?? null };
  });
});
